/*
 Problem: 3014. Minimum Number of Pushes to Type Word I
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.1 MB (95.18%)
 Tags: Math, String, Greedy
*/
class Solution {
public:
    int minimumPushes(string word) {
        int ans = 0;

        for (int i = 0; i < word.size(); ++i) {
            ans += i / 8 + 1;
        }

        return ans;
    }
};
